func findPath(tr *Tree, from string) []*Tree {
	if tr == nil {
		return nil
	}
	if tr.value == from {
		return []*Tree{tr}
	}
	for _, ch := range tr.children {
		if p := findPath(ch, from); p != nil {
			return append([]*Tree{tr}, p...)
		}
	}
	return nil
