// reroot rebuilds the tree so that the last node in path becomes the root.
// path[0] is the original root and path[i] is a child of path[i-1].
// Each node keeps its other children; the reoriented subtree is attached
// as a child of each ancestor, and the ancestor chain is attached to the
// new root.
func reroot(path []*Tree) *Tree {
	root := &Tree{value: path[len(path)-1].value, children: append([]*Tree{}, path[len(path)-1].children...)}
	for i := len(path) - 2; i >= 0; i-- {
		node := &Tree{value: path[i].value}
		node.children = make([]*Tree, 0, len(path[i].children)+1)
		for _, ch := range path[i].children {
			if ch != path[i+1] {
				node.children = append(node.children, ch)
			}
		}
		node.children = append(node.children, root)
		root = node
	}
	return root
}

